import React, { useState, useEffect, useRef } from 'react';
import {
    Calendar,
    MapPin,
    Clock,
    Heart,
    ChevronDown,
    Music,
    Music2,
    Upload,
    Phone,
    Home,
    MailOpen,
    Menu,
    X
} from 'lucide-react';

function App() {
    const [activeTab, setActiveTab] = useState('home');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isVisible, setIsVisible] = useState(true);
    const [overlayVisible, setOverlayVisible] = useState(true);
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [rsvpName, setRsvpName] = useState('');
    const [rsvpMessage, setRsvpMessage] = useState('');
    const [rsvpSubmitted, setRsvpSubmitted] = useState(false);
    const [countdown, setCountdown] = useState({});
    const audioRef = useRef(null);

    const weddingDateStr = "May 21, 2026 20:00:00";
    const weddingDate = "May 21, 2026";
    const weddingTime = "08:00 PM";
    const locationAddress = "No.60, Moor Street, Kalutara South.";
    const contactNumber = "+94 77 688 9699";
    const googleDriveLink =
        "https://drive.google.com/drive/folders/1-kykFeDTzB3kiq8k840hlp0vAsrGerN2?usp=sharing";

    // Fade animation
    useEffect(() => {
        setIsVisible(false);
        const timer = setTimeout(() => setIsVisible(true), 100);
        return () => clearTimeout(timer);
    }, [activeTab]);

    // Play/pause audio
    useEffect(() => {
        if (audioRef.current) {
            if (isPlaying) audioRef.current.play();
            else audioRef.current.pause();
        }
    }, [isPlaying]);

    // Countdown
    useEffect(() => {
        const weddingTimeDate = new Date(weddingDateStr).getTime();
        const interval = setInterval(() => {
            const now = new Date().getTime();
            const distance = weddingTimeDate - now;

            if (distance < 0) {
                clearInterval(interval);
                setCountdown({ expired: true });
            } else {
                const days = Math.floor(distance / (1000 * 60 * 60 * 24));
                const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
                const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
                const seconds = Math.floor((distance % (1000 * 60)) / 1000);
                setCountdown({ days, hours, minutes, seconds });
            }
        }, 1000);
        return () => clearInterval(interval);
    }, []);

    const TabButton = ({ id, label, icon: Icon }) => (
        <button
            onClick={() => {
                setActiveTab(id);
                setMobileMenuOpen(false);
            }}
            className={`flex items-center space-x-2 px-3 py-2 rounded-full transition-all duration-300 text-sm md:text-xs ${
                activeTab === id
                    ? 'bg-[#D4AF37] text-white'
                    : 'text-[#4A4238] hover:bg-[#D4AF37]/20'
            }`}
        >
            <Icon size={16} />
            <span className="uppercase tracking-widest font-bold">{label}</span>
        </button>
    );

    const handleOverlayClick = () => {
        if (audioRef.current) {
            audioRef.current.play();
            setIsPlaying(true);
        }
        setOverlayVisible(false);
    };

    const handleRsvpSubmit = (e) => {
        e.preventDefault();
        if (!rsvpName) return;
        setRsvpSubmitted(true);
        setRsvpName('');
        setRsvpMessage('');
    };

    return (
        <div className="min-h-screen bg-[#FFFBF5] text-[#4A4238] font-serif relative">

            {/* Audio */}
            <audio ref={audioRef} src="/audio/fathiha.mp3" loop />

            {/* Overlay */}
            {overlayVisible && (
                <div
                    onClick={handleOverlayClick}
                    className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center text-white text-center px-4 cursor-pointer"
                >
                    <div>
                        <p className="text-2xl md:text-4xl font-semibold">
                            Tap anywhere to start audio
                        </p>
                        <p className="text-sm mt-2 opacity-70">
                            Please allow audio to enjoy the experience
                        </p>
                    </div>
                </div>
            )}

            {/* NAVBAR */}
            <nav className="fixed top-0 w-full z-40 bg-white/70 backdrop-blur border-b border-[#D4AF37]/20 px-4 md:px-6 py-4">
                <div className="max-w-6xl mx-auto flex justify-between items-center">
                    <h2 className="text-xl italic">
                        Shazeen <span className="text-[#D4AF37]">&</span> Shimra
                    </h2>
                    <div className="hidden md:flex space-x-2">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="rsvp" label="RSVP" icon={Heart} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>
                    <div className="md:hidden">
                        <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
                            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>
                {mobileMenuOpen && (
                    <div className="flex flex-col items-center space-y-2 mt-2 md:hidden">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="rsvp" label="RSVP" icon={Heart} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>
                )}
            </nav>

            {/* MAIN CONTENT */}
            <main className={`pt-28 px-4 md:px-6 lg:px-12 transition-all duration-700 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>

                {/* HOME */}
                {activeTab === 'home' && (
                    <section className="min-h-[80vh] flex flex-col items-center justify-center text-center space-y-6 md:space-y-8 px-2 md:px-0">

                        <span className="border-y border-[#D4AF37] px-4 py-1 text-[#D4AF37] text-xs tracking-[0.3em] uppercase">
                            Together with their families
                        </span>

                        <h1 className="text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-light italic text-center leading-tight">
                            Shazeen
                            <span className="text-[#D4AF37] mx-2 md:mx-4">&</span>
                            Shimra
                        </h1>

                        <p className="italic opacity-70 text-lg md:text-xl">
                            Cordially invite you to celebrate their
                            <span className="block text-2xl md:text-3xl mt-2 not-italic">
                                Wedding Function
                            </span>
                        </p>

                        {/* Location on Home */}
                        <div className="flex flex-col md:flex-row gap-6 md:gap-8 items-center mt-6 md:mt-8 w-full max-w-4xl">
                            <div className="flex-1 bg-white/50 rounded-3xl p-6 md:p-8 shadow-xl flex flex-col items-center justify-center space-y-2 md:space-y-4 min-h-[200px] w-full">
                                <MapPin className="text-[#D4AF37]" size={32} />
                                <h3 className="text-lg md:text-xl font-semibold">Pearl Grand Banquet Hall</h3>
                                <p className="text-sm md:text-base opacity-80">{locationAddress}</p>
                                <a
                                    href={`tel:${contactNumber}`}
                                    className="flex items-center space-x-2 mt-2 text-[#D4AF37] font-semibold"
                                >
                                    <Phone size={16} />
                                    <span>{contactNumber}</span>
                                </a>
                            </div>

                            <div className="flex-1 w-full min-h-[200px] relative overflow-hidden rounded-3xl shadow-xl">
                                <iframe
                                    title="Wedding Location"
                                    src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3963.5946305073207!2d79.9692585!3d6.572735099999999!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3ae237006541d533%3A0x83c56abe1a801459!2sPearl%20Grand%20Banquet%20Hall!5e0!3m2!1sen!2slk!4v1769275470162!5m2!1sen!2slk"
                                    className="absolute inset-0 w-full h-full"
                                    style={{ border: 0 }}
                                    allowFullScreen
                                    loading="lazy"
                                    referrerPolicy="no-referrer-when-downgrade"
                                />
                            </div>
                        </div>

                        {/* Countdown BELOW Location */}
                        <div className="mt-6 md:mt-8 flex flex-wrap justify-center gap-4 md:gap-6 text-[#D4AF37]">
                            {countdown.expired ? (
                                <span className="text-2xl md:text-4xl font-bold">Wedding Day is Here!</span>
                            ) : (
                                <>
                                    <div className="bg-[#D4AF37]/10 px-4 py-2 md:px-6 md:py-3 rounded-2xl shadow-lg">
                                        <span className="text-2xl md:text-4xl font-bold">{countdown.days}</span>
                                        <span className="block text-sm md:text-base mt-1 uppercase tracking-widest">Days</span>
                                    </div>
                                    <div className="bg-[#D4AF37]/10 px-4 py-2 md:px-6 md:py-3 rounded-2xl shadow-lg">
                                        <span className="text-2xl md:text-4xl font-bold">{countdown.hours}</span>
                                        <span className="block text-sm md:text-base mt-1 uppercase tracking-widest">Hours</span>
                                    </div>
                                    <div className="bg-[#D4AF37]/10 px-4 py-2 md:px-6 md:py-3 rounded-2xl shadow-lg">
                                        <span className="text-2xl md:text-4xl font-bold">{countdown.minutes}</span>
                                        <span className="block text-sm md:text-base mt-1 uppercase tracking-widest">Minutes</span>
                                    </div>
                                    <div className="bg-[#D4AF37]/10 px-4 py-2 md:px-6 md:py-3 rounded-2xl shadow-lg">
                                        <span className="text-2xl md:text-4xl font-bold">{countdown.seconds}</span>
                                        <span className="block text-sm md:text-base mt-1 uppercase tracking-widest">Seconds</span>
                                    </div>
                                </>
                            )}
                        </div>

                        <button
                            onClick={() => setActiveTab('invitation')}
                            className="flex flex-col items-center text-[#D4AF37] mt-6"
                        >
                            <span className="text-xs uppercase tracking-widest font-bold">
                                More Details
                            </span>
                            <ChevronDown className="animate-bounce mt-1 md:mt-2" />
                        </button>
                    </section>
                )}

                {/* The rest of Invitation, RSVP, Location sections remain unchanged */}

            </main>
        </div>
    );
}

export default App;
